#include "Pitch.h"
#include "Dsp.h"
#include <cmath>
#include <algorithm>
#include <random>
#include <iostream>
#include <stdexcept>
namespace {void check(bool x,const char* message){if(!x)throw std::runtime_error(message);}vocal::AudioChannels tone(double hz,double seconds=1.6,int channels=1){const int n=static_cast<int>(48000*seconds);vocal::AudioChannels x(channels,std::vector<float>(n));for(int i=0;i<n;++i){const double t=i/48000.0,fade=std::min(1.0,std::min(t/.03,(seconds-t)/.03));const float v=static_cast<float>(fade*(.16*std::sin(2*vocal::pi*hz*t)+.08*std::sin(4*vocal::pi*hz*t)+.04*std::sin(6*vocal::pi*hz*t)));for(auto& c:x)c[i]=v;}return x;}}
int main(){try {std::atomic<bool> cancel{false};std::atomic<float> progress{0};for(double hz:{65.406,110.0,220.0,440.0,698.456}){auto result=vocal::analysePitch(tone(hz),48000,true,cancel,progress);check(result.voicedFraction>.85,"voiced detection");const double cents=1200*std::log2(result.medianHz/hz);std::cout<<hz<<" Hz: "<<result.medianHz<<" ("<<cents<<" cents)\n";check(std::abs(cents)<8,"pitch accuracy with harmonics");}
    vocal::AudioChannels silence(1,std::vector<float>(48000));check(vocal::analysePitch(silence,48000,true,cancel,progress).medianHz==0,"silence must have no pitch");check(vocal::analysePitch(tone(440),48000,true,cancel,progress).tonic<0,"single note is insufficient to infer key");
    std::mt19937 random(174);std::uniform_real_distribution<float> distribution(-.1f,.1f);auto noise=silence;for(float& x:noise[0])x=distribution(random);auto noiseAnalysis=vocal::analysePitch(noise,48000,true,cancel,progress);check(noiseAnalysis.voicedFraction<.03,"noise must not be reported as a reliable singing pitch");auto inverted=tone(220,1.5,2);for(float& x:inverted[1])x=-x;check(std::abs(vocal::analysePitch(inverted,48000,true,cancel,progress).medianHz-220)<1,"phase-inverted stereo detection fallback");
    check(vocal::nearestScaleNote(61.1,0,false)==62,"C major scale snapping");check(vocal::nearestScaleNote(63.1,0,true)==63,"C minor scale snapping");
    auto input=tone(220,2.5,2);vocal::PitchOptions options;options.semitones=3;options.preserveFormants=false;auto shifted=vocal::processPitch(input,48000,options,nullptr,cancel,progress);check(shifted.size()==2&&shifted[0].size()==input[0].size(),"pitch shift preserves channels and exact duration");auto measured=vocal::analysePitch(shifted,48000,true,cancel,progress);std::cout<<"shifted: "<<measured.medianHz<<" Hz\n";check(std::abs(1200*std::log2(measured.medianHz/(220*std::pow(2,3.0/12))))<12,"transpose semitone accuracy");double difference=0,energy=0;for(std::size_t i=0;i<shifted[0].size();++i){check(std::isfinite(shifted[0][i])&&std::isfinite(shifted[1][i]),"finite stereo samples");difference+=std::pow(shifted[0][i]-shifted[1][i],2);energy+=std::pow(shifted[0][i],2);}std::cout<<"stereo RMS difference ratio: "<<std::sqrt(difference/energy)<<"\n";check(difference/energy<.000001,"stereo coherence");
    options={};options.correction=1;options.retuneMs=20;options.toleranceCents=0;options.preserveFormants=true;auto detuned=tone(440*std::pow(2,.35/12),2.5);auto analysis=vocal::analysePitch(detuned,48000,true,cancel,progress);auto corrected=vocal::processPitch(detuned,48000,options,&analysis,cancel,progress);measured=vocal::analysePitch(corrected,48000,true,cancel,progress);std::cout<<"corrected: "<<measured.medianHz<<" Hz\n";check(std::abs(1200*std::log2(measured.medianHz/440))<12,"automatic pitch correction");
    vocal::AudioChannels melody(1);for(double hz:{261.625565,329.627557,391.995436,349.228231,440.0,493.883301,293.664768,261.625565}){auto note=tone(hz,hz==261.625565?.9:.4);melody[0].insert(melody[0].end(),note[0].begin(),note[0].end());}auto key=vocal::analysePitch(melody,48000,true,cancel,progress);std::cout<<"key: "<<key.tonic<<" minor="<<key.minor<<" confidence="<<key.keyConfidence<<" alternative="<<key.alternative<<"\n";check(key.tonic==0&&!key.minor,"C major melody key detection");
    auto clipped=tone(220);for(auto& x:clipped[0])x=std::clamp(x*6,-1.0f,1.0f);auto repaired=vocal::repairLightClipping(clipped,48000);std::size_t changed=0;for(std::size_t i=0;i<clipped[0].size();++i)if(std::abs(repaired[0][i]-clipped[0][i])>.001)++changed;check(changed>100,"short clipping plateaus repaired");
    vocal::AudioChannels progression(1);for(const auto& chord:std::vector<std::vector<double>>{{261.625565,329.627557,391.995436},{349.228231,440,523.251131},{391.995436,493.883301,587.329536},{261.625565,329.627557,391.995436}}){auto section=tone(chord[0],1.3);for(std::size_t i=0;i<section[0].size();++i){section[0][i]=0;for(double hz:chord)section[0][i]+=static_cast<float>(.08*std::sin(2*vocal::pi*hz*i/48000));}progression[0].insert(progression[0].end(),section[0].begin(),section[0].end());}auto chordKey=vocal::analysePitch(progression,48000,false,cancel,progress);std::cout<<"polyphonic key: "<<chordKey.tonic<<" minor="<<chordKey.minor<<"\n";check(chordKey.tonic==0&&!chordKey.minor,"polyphonic chord progression key detection");
    options={};options.semitones=-5;options.preserveFormants=false;auto lowered=vocal::processPitch(input,48000,options,nullptr,cancel,progress);auto lowAnalysis=vocal::analysePitch(lowered,48000,true,cancel,progress);check(std::abs(1200*std::log2(lowAnalysis.medianHz/(220*std::pow(2,-5.0/12))))<12,"lowering tone accuracy");
    vocal::AudioChannels hardClipped(1,std::vector<float>(48000)),unclipped=hardClipped;for(std::size_t i=0;i<hardClipped[0].size();++i){unclipped[0][i]=1.25f*std::sin(static_cast<float>(2*vocal::pi*220*i/48000));hardClipped[0][i]=std::clamp(unclipped[0][i],-1.0f,1.0f);}auto repairedSine=vocal::repairLightClipping(hardClipped,48000);double beforeError=0,afterError=0;for(std::size_t i=0;i<hardClipped[0].size();++i){beforeError+=std::pow(hardClipped[0][i]-unclipped[0][i],2);afterError+=std::pow(repairedSine[0][i]-unclipped[0][i],2);}std::cout<<"short-clip error ratio: "<<afterError/beforeError<<"\n";check(afterError<beforeError*.5,"repair must reduce known short-clip waveform error");
    options={};options.correction=1;options.retuneMs=20;options.toleranceCents=0;options.tonic=0;options.semitones=2;auto sourceE=tone(329.627557*std::pow(2,.35/12),2.5);auto sourceEAnalysis=vocal::analysePitch(sourceE,48000,true,cancel,progress);auto targetG=vocal::processPitch(sourceE,48000,options,&sourceEAnalysis,cancel,progress);auto targetGAnalysis=vocal::analysePitch(targetG,48000,true,cancel,progress);check(std::abs(1200*std::log2(targetGAnalysis.medianHz/391.995436))<12,"correction must target output scale after transpose");
    options={};options.correction=1;options.retuneMs=20;options.toleranceCents=0;options.cents=static_cast<float>(1200*std::log2(432.0/440));auto fine=vocal::processPitch(detuned,48000,options,&analysis,cancel,progress);check(std::abs(1200*std::log2(vocal::analysePitch(fine,48000,true,cancel,progress).medianHz/432))<12,"fine cents apply after pitch correction");
    vocal::AudioChannels minorMelody(1);for(double hz:{220.0,261.625565,329.627557,293.664768,349.228231,391.995436,246.941651,220.0}){auto note=tone(hz,hz==220?.9:.4);minorMelody[0].insert(minorMelody[0].end(),note[0].begin(),note[0].end());}auto minorKey=vocal::analysePitch(minorMelody,48000,true,cancel,progress);std::cout<<"minor key: "<<minorKey.tonic<<" minor="<<minorKey.minor<<"\n";check(minorKey.tonic==9&&minorKey.minor,"A minor melody key detection");
    options={};auto bypass=vocal::processPitch(input,48000,options,nullptr,cancel,progress);check(bypass==input,"zero transpose is bit-exact");cancel.store(true);options.semitones=2;check(vocal::processPitch(input,48000,options,nullptr,cancel,progress).empty(),"pitch render cancellation");std::cout<<"PASS: F0, scale, transpose, correction, stereo, duration, bypass and cancellation\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
